<script setup>
import {computed,ref} from 'vue'
import {useCreation} from '@/ports/creation'
import Icon from '../components/CreationIcon.vue'
import ProductScene from '../components/ProductScene.vue'
const p=useCreation(),s=p.state
const keys=['number','duration','scale','camera','visual','sound','emotion','environment','imagePrompt','motionPrompt']
const nodeIcons={'文字':'text','图片':'image','视频':'video','音频':'audio','脚本':'script'}
const sessionMenu=ref(false),showAgent=ref(true),canvas=ref(null)
const edges=computed(()=>s.nodes.filter(n=>n.rowId).map(n=>({id:n.id,path:`M 1090 ${220+s.rows.findIndex(r=>r.id===n.rowId)*102} C 1140 ${220+s.rows.findIndex(r=>r.id===n.rowId)*102}, ${n.x-70} ${n.y+88}, ${n.x} ${n.y+88}`})))
function drag(e,n){if(e.button!==0||s.readonly)return;const x=e.clientX,y=e.clientY,ox=n.x,oy=n.y;const move=ev=>p.moveNode(n.id,ox+(ev.clientX-x)/(s.zoom/100),oy+(ev.clientY-y)/(s.zoom/100));const end=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',end)}
function focusNode(){canvas.value?.scrollTo({left:1000,top:80,behavior:'smooth'})}
function reset(){canvas.value?.scrollTo({left:0,top:0,behavior:'smooth'});s.zoom=100}
</script>
<template><div class="workspace-page"><header class="workspace-header"><div class="project-breadcrumb"><button class="icon-button" title="返回项目" @click="p.go('home')"><Icon name="back"/></button><span class="small-project-icon"><Icon name="folder"/></span><button class="project-title" @click="p.openModal('rename-project')">{{s.projectName}}<Icon name="down" :size="13"/></button><span class="subtle-chip"><i></i>已保存</span></div><div class="header-actions"><span v-if="s.readonly" class="readonly-label">只读项目</span><button class="ghost-button" @click="p.openModal('tasks')"><Icon name="clock"/>任务<span v-if="s.tasks.length" class="tiny-count">{{s.tasks.length}}</span></button><button class="secondary-button" @click="p.openModal('feedback')">确认与反馈</button><button class="primary-button" @click="p.openModal('download')"><Icon name="download" :size="16"/>下载素材</button></div></header><div class="workspace-toolbar"><div class="canvas-tab"><Icon name="layers" :size="16"/>主画布<span>01</span></div><div class="toolbar-divider"></div><button v-for="[type,icon] in Object.entries(nodeIcons)" :key="type" :disabled="s.readonly" @click="type==='脚本'?(s.nodes.some(n=>n.id==='script')?p.notify('分镜表已在画布中'):s.nodes.push({id:'script',type:'脚本',name:'分镜脚本',x:44,y:74})):p.addNode(type)"><Icon :name="icon" :size="16"/>{{type}}</button><div class="toolbar-spacer"></div><button @click="p.openModal('reference',{for:'canvas'})"><Icon name="attach" :size="15"/>引用</button><button class="active-tool" @click="showAgent=!showAgent"><Icon name="spark" :size="15"/>灵感助手</button></div><div class="workspace-body"><section ref="canvas" class="canvas-viewport" aria-label="创作画布"><div v-if="s.loading" class="canvas-state"><div class="spinner"></div><h3>正在载入你的创作…</h3><button class="secondary-button" @click="p.retry()">显示内容</button></div><div v-else-if="s.failed" class="canvas-state"><h3>画布暂时加载失败</h3><p>已有节点和素材仍然保留。</p><button class="secondary-button" @click="p.retry()">重新加载</button></div><div v-else class="canvas-stage" :style="{transform:`scale(${s.zoom/100})`}"><svg class="edge-layer" width="2250" height="1800" aria-label="镜头行连接"><defs><linearGradient id="edgeGradient"><stop stop-color="#9b7cf8"/><stop offset="1" stop-color="#6e58af"/></linearGradient></defs><path v-for="e in edges" :key="e.id" :d="e.path" stroke="url(#edgeGradient)" stroke-width="1.8" fill="none"/></svg><article v-for="n in s.nodes" :key="n.id" class="canvas-node" :class="[n.type==='脚本'?'script-node':'media-node',{selected:s.selectedNode===n.id}]" :style="{left:n.x+'px',top:n.y+'px'}" @click="s.selectedNode=n.id"><header class="node-header" @pointerdown="drag($event,n)"><span class="node-type-icon" :class="n.type"><Icon :name="nodeIcons[n.type]" :size="16"/></span><strong>{{n.name}}</strong><span class="node-mini-tag">{{n.type}}</span><button class="icon-button" :title="n.type==='脚本'?'编辑分镜表':'删除节点'" @pointerdown.stop @click.stop="n.type==='脚本'?p.openModal('script-editor'):p.deleteNode(n.id)"><Icon :name="n.type==='脚本'?'expand':'more'" :size="16"/></button></header><template v-if="n.type==='脚本'"><div class="script-caption"><span><i class="status-dot"></i>{{s.rows.length}} 个镜头<span class="muted"> · 每行独立连接下游节点</span></span><button class="subtle-button" @click="p.exportPreview('excel')"><Icon name="download" :size="14"/>Excel</button></div><div class="script-table-scroll"><table class="script-table"><thead><tr><th class="row-selection"><input type="checkbox" aria-label="全选镜头" :checked="s.rows.length>0&&s.selectedRows.length===s.rows.length" @change="s.selectedRows=$event.target.checked?s.rows.map(x=>x.id):[]"/></th><th v-for="c in s.columns" :key="c">{{c}}</th><th class="row-outlet-heading">连接</th></tr></thead><tbody><tr v-for="row in s.rows" :key="row.id" :class="{chosen:s.selectedRows.includes(row.id)}"><td class="row-selection"><input type="checkbox" :aria-label="'选择镜头'+row.number" :checked="s.selectedRows.includes(row.id)" @change="p.toggleRow(row.id)"/></td><td v-for="key in keys" :key="key"><span v-if="key==='number'" class="shot-number">{{row[key]}}</span><span v-else-if="key==='duration'" class="duration-pill">{{row[key]}}</span><p v-else :title="row[key]">{{row[key]||'—'}}</p></td><td class="row-outlet-cell"><button class="row-outlet" :aria-label="'连接镜头'+row.number" :title="'连接镜头'+row.number+'到下游节点'" @click.stop="s.pendingRow=s.pendingRow===row.id?null:row.id"><Icon name="plus" :size="13"/></button></td></tr><tr v-if="!s.rows.length"><td colspan="12" class="table-empty">输入故事或引用资料，生成你的第一份分镜。</td></tr></tbody></table></div><div class="script-footer"><button class="subtle-button" :disabled="s.readonly" @click="p.addRow()"><Icon name="plus" :size="15"/>添加镜头</button><span><Icon name="link" :size="13"/>点击行右侧连接点，将内容引用到节点</span><button class="subtle-button" @click="p.openModal('script-input')">输入与引用<Icon name="arrow" :size="14"/></button></div></template><template v-else><div v-if="n.rowId" class="node-reference" @click="p.openModal('row-reference',{node:n})"><span class="reference-dot"></span>引用镜头 {{p.row(n.rowId)?.number}}<Icon name="link" :size="12"/></div><div v-if="n.status==='running'" class="node-render-state"><div class="spinner"></div><b>正在生成创作结果</b><span>当前输入和参考版本已固定</span></div><div v-else-if="n.status==='success'" class="node-media" @contextmenu.prevent="p.openModal('save',{type:n.type,name:n.name,scene:n.scene})"><ProductScene :variant="n.scene"/><button v-if="n.type==='视频'" class="video-play" title="播放预览" @click="p.openModal('media-preview',n)"><Icon name="play" :size="25"/></button><span class="image-resolution">{{n.type==='视频'?'00:05':'1920 × 1080'}}<span>版本 1</span></span><div class="media-hover-actions"><button title="保存为资产" @click="p.openModal('save',{type:n.type,name:n.name,scene:n.scene})"><Icon name="save" :size="15"/></button><button title="下载素材" @click="p.openModal('download',{node:n})"><Icon name="download" :size="15"/></button></div></div><div v-else-if="n.type==='文字'" class="text-node-preview"><p>{{n.text||'设定创作目标与风格，让灵感在这里展开。'}}</p><button class="subtle-button" @click="p.openModal('text-editor',{node:n})">详情<Icon name="arrow" :size="14"/></button></div><div v-else class="empty-media"><Icon :name="nodeIcons[n.type]" :size="28"/><span>你的{{n.type}}将在这里呈现</span></div><p v-if="n.stale" class="node-stale">来源已更新 · 原结果保留</p><div class="node-input"><textarea :value="n.prompt" :aria-label="n.name+'提示词'" :placeholder="n.rowId?'添加补充要求，或直接使用已引用的分镜内容…':'输入目标设定与风格，或引用参考内容…'" :disabled="s.readonly" @input="p.setNode(n.id,'prompt',$event.target.value)"></textarea><div class="node-input-tools"><button title="引用" @click="p.openModal('reference',{for:'node',node:n})"><Icon name="attach" :size="14"/></button><button v-if="n.type!=='文字'" title="优化提示词" @click="p.openModal('optimize',{node:n})"><Icon name="spark" :size="14"/></button><button title="保存提示词为资产" @click="p.openModal('save',{type:'提示词',text:n.prompt||p.referenceText(n),name:''})"><Icon name="save" :size="14"/></button><span v-if="n.rowId">已引用 1 行</span></div></div><div v-if="n.type==='视频'" class="video-mode"><select :value="n.mode" aria-label="视频生成方式" @change="p.setNode(n.id,'mode',$event.target.value)"><option>图生视频</option><option>文生视频</option></select><button v-if="n.mode==='图生视频'" :class="{confirmed:n.imageConfirmed}" @click="p.referenceImage(n.id)"><Icon :name="n.imageConfirmed?'check':'image'" :size="13"/>{{n.imageConfirmed?'图片版本已确认':'选择并确认图片'}}</button></div><div class="node-controls"><span class="node-model">{{n.type==='视频'?'万相 3.0':n.type==='音频'?'Seed Audio1.0':n.type==='文字'?'Qwen Flash':'千问图像 3.0'}}<Icon name="down" :size="11"/></span><select :value="n.ratio" aria-label="画面比例" @change="p.setNode(n.id,'ratio',$event.target.value)"><option>16:9</option><option>9:16</option><option>1:1</option></select><button class="node-generate" :disabled="n.status==='running'||s.readonly" @click="n.type==='文字'?p.openModal('text-editor',{node:n}):p.requestGenerate(n.id)"><Icon name="spark" :size="14"/>{{n.status==='success'?'再生成':'生成'}}</button></div></template></article><div v-if="s.pendingRow" class="connect-popover" :style="{left:'1100px',top:(225+s.rows.findIndex(r=>r.id===s.pendingRow)*102)+'px'}"><span class="eyebrow">引用镜头 {{p.row(s.pendingRow)?.number}}</span><h4>连接到新节点</h4><button v-for="t in ['图片','视频','音频','文字']" :key="t" @click="p.addNode(t,s.pendingRow);focusNode()"><Icon :name="nodeIcons[t]"/>{{t}}节点<Icon name="plus" :size="14"/></button><div class="popover-label">或连接到已有节点</div><button v-for="n in s.nodes.filter(n=>n.type!=='脚本')" :key="n.id" @click="p.connect(s.pendingRow,n.id)"><Icon :name="nodeIcons[n.type]"/>{{n.name}}</button></div></div><div v-if="!s.nodes.length&&!s.loading" class="canvas-state"><Icon name="layers" :size="35"/><h3>画布，准备好了</h3><p>添加节点，或让灵感助手帮你开始。</p><button class="primary-button" @click="s.nodes.push({id:'script',type:'脚本',name:'分镜脚本',x:44,y:74})">添加脚本节点</button></div></section><aside v-if="showAgent" class="agent-panel"><header><span class="agent-avatar"><Icon name="spark" :size="18"/></span><div><strong>灵感助手</strong><small>一起把想法变成画面</small></div><button class="icon-button" title="收起助手" @click="showAgent=false"><Icon name="close" :size="16"/></button></header><div class="session-selector"><select :value="s.activeSession" @change="p.switchSession($event.target.value)" aria-label="切换会话"><option v-for="name in s.sessions" :key="name">{{name}}</option></select><button class="icon-button" title="创建会话" @click="p.newSession()"><Icon name="plus" :size="16"/></button><button class="icon-button" title="会话操作" @click="sessionMenu=!sessionMenu"><Icon name="more" :size="16"/></button><div v-if="sessionMenu" class="session-menu"><button @click="p.openModal('rename-session');sessionMenu=false">重命名会话</button><button @click="p.openModal('delete-session');sessionMenu=false">删除会话</button></div></div><div class="agent-messages"><div class="chat-date">今天</div><article v-for="(m,i) in s.messages" :key="i" class="chat-message" :class="m.role"><div class="message-role"><Icon v-if="m.role==='assistant'" name="spark" :size="13"/>{{m.role==='assistant'?'灵感助手':'你'}}</div><p>{{m.text}}</p><button v-if="m.role==='user'" class="message-edit" title="编辑消息后重发" @click="s.agentText=m.text"><Icon name="edit" :size="12"/>编辑重发</button><div v-if="m.tool" class="tool-result"><Icon name="check" :size="12"/>{{m.tool}}</div><div v-if="m.plan" class="agent-plan"><b>画布操作计划</b><span>创建 1 个图片节点</span><span>引用镜头 01 · 保留已有内容</span><button class="primary-button" @click="p.acceptPlan();m.plan=false">确认创建<Icon name="arrow" :size="13"/></button></div></article><div v-if="s.busy" class="typing-dots"><i></i><i></i><i></i><span>正在整理思路…</span></div><div class="agent-suggestion"><span>接下来可以试试</span><button @click="s.agentText='为镜头01创建一个图片节点'">为分镜创建图片节点<Icon name="arrow" :size="13"/></button><button @click="p.openModal('question')">调整整片的视觉风格<Icon name="arrow" :size="13"/></button></div></div><div class="agent-composer"><textarea v-model="s.agentText" aria-label="与Agent对话" placeholder="告诉我你的想法，或 @ 引用内容…" @keydown.ctrl.enter="p.sendAgent()"></textarea><div><button class="icon-button" title="引用项目或资产" @click="p.openModal('reference',{for:'agent'})"><Icon name="attach" :size="16"/></button><span>Qwen 3.8 Flash</span><button class="send-button" title="发送" :disabled="s.busy" @click="p.sendAgent()"><Icon name="arrow" :size="16"/></button></div></div><p class="agent-disclaimer">生成前确认范围，创意始终由你掌握</p></aside></div><div class="canvas-bottom-toolbar"><button class="icon-button" title="撤销" @click="p.notify('当前没有可撤销的编辑')"><Icon name="undo" :size="16"/></button><span class="toolbar-divider"></span><button class="icon-button" title="缩小" @click="s.zoom=Math.max(50,s.zoom-10)">−</button><span>{{s.zoom}}%</span><button class="icon-button" title="放大" @click="s.zoom=Math.min(150,s.zoom+10)">+</button><span class="toolbar-divider"></span><button class="icon-button" title="适应画布" @click="reset()"><Icon name="expand" :size="16"/></button></div><div class="canvas-position-note">无限画布<span>滚动探索 · 拖动标题移动节点</span></div></div></template>
